@import "tailwindcss";

@theme {
  --color-gold: #d4af37;
  --color-gold-dark: #aa8010;
  --color-gold-light: #f3e5ab;
  --color-ethioGreen: #078732;
  --color-ethioYellow: #fcd116;
  --color-ethioRed: #e51f1f;
}

body {
  background-color: #0a0b0d; /* Premium luxury dark mode background */
  color: #f3f4f6;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  overflow-x: hidden;
}

a {
  text-decoration: none;
}

/* Hide scrollbar for Chrome, Safari and Opera */
.no-scrollbar::-webkit-scrollbar {
  display: none;
}

/* Hide scrollbar for IE, Edge and Firefox */
.no-scrollbar {
  -ms-overflow-style: none;  /* IE and Edge */
  scrollbar-width: none;  /* Firefox */
}

/* Custom sleek scrollbar for intentional scroll areas */
.custom-scrollbar::-webkit-scrollbar {
  height: 4px;
  width: 4px;
}
.custom-scrollbar::-webkit-scrollbar-track {
  background: rgba(255, 255, 255, 0.03);
}
.custom-scrollbar::-webkit-scrollbar-thumb {
  background: rgba(212, 175, 55, 0.3);
  border-radius: 2px;
}
.custom-scrollbar::-webkit-scrollbar-thumb:hover {
  background: rgba(212, 175, 55, 0.6);
}

/* =========================================================
   MOTION SYSTEM — Habsha Kamiss luxury homepage
   Focal idea: "woven in" hero reveal + mannequin tilt
   ========================================================= */

@keyframes hk-rise-in {
  from { transform: translateY(115%); }
  to   { transform: translateY(0); }
}

@keyframes hk-fade-up {
  from { opacity: 0; transform: translateY(18px); }
  to   { opacity: 1; transform: translateY(0); }
}

@keyframes hk-thread-draw {
  from { transform: scaleX(0); }
  to   { transform: scaleX(1); }
}

@keyframes hk-glow-drift {
  0%, 100% { transform: translate3d(0, 0, 0) scale(1); }
  50%      { transform: translate3d(50px, -40px, 0) scale(1.08); }
}

@keyframes hk-float {
  0%, 100% { transform: translateY(0); }
  50%      { transform: translateY(-12px); }
}

@keyframes hk-sheen {
  to { transform: skewX(-20deg) translateX(340%); }
}

/* Loom weaving backdrop: threads drawn via normalized pathLength dash offset */
@keyframes hk-weave-x {
  from { stroke-dashoffset: 1; }
  to   { stroke-dashoffset: 0; }
}

@keyframes hk-weave-x-rev {
  from { stroke-dashoffset: -1; }
  to   { stroke-dashoffset: 0; }
}

@keyframes hk-weave-y {
  from { stroke-dashoffset: 1; }
  to   { stroke-dashoffset: 0; }
}

@keyframes hk-shuttle-run {
  from { stroke-dashoffset: 1; }
  to   { stroke-dashoffset: 0; }
}

.hk-weft-line,
.hk-warp-line {
  stroke-dasharray: 1;
}
.hk-weft-line {
  animation: hk-weave-x 3s ease-out forwards;
}
.hk-weft-line[data-dir="rev"] {
  animation-name: hk-weave-x-rev;
}
.hk-warp-line {
  animation: hk-weave-y 3.4s ease-out forwards;
}
.hk-shuttle {
  stroke-dasharray: 0.16 0.84;
  animation: hk-shuttle-run 5.5s linear infinite;
}

/* Masked line reveal: parent clips, child rises */
.hk-mask {
  display: block;
  overflow: hidden;
  padding-bottom: 0.08em;
  margin-bottom: -0.08em;
}
.hk-rise {
  display: inline-block;
  transform: translateY(115%);
  animation: hk-rise-in 1s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}

/* Soft entrance for supporting elements */
.hk-fade-up {
  opacity: 0;
  animation: hk-fade-up 0.9s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}

/* The gold thread: a hairline that draws itself left to right */
.hk-thread {
  transform-origin: left center;
  transform: scaleX(0);
  animation: hk-thread-draw 1.4s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}

/* Slow ambient background drifts (bounded, cheap) */
.hk-glow-a { animation: hk-glow-drift 20s ease-in-out infinite; }
.hk-glow-b { animation: hk-glow-drift 26s ease-in-out infinite reverse; }

/* Gentle levitation for the hero garment */
.hk-float { animation: hk-float 7s ease-in-out infinite; }

/* Gold light sweep across the primary CTA on hover */
.btn-sheen { position: relative; overflow: hidden; }
.btn-sheen::before {
  content: "";
  position: absolute;
  inset: -2px;
  width: 60%;
  background: linear-gradient(105deg, transparent, rgba(255, 255, 255, 0.5), transparent);
  transform: skewX(-20deg) translateX(-240%);
}
.btn-sheen:hover::before {
  animation: hk-sheen 0.8s cubic-bezier(0.16, 1, 0.3, 1);
}

/* Accessibility: stillness for users who ask for it */
@media (prefers-reduced-motion: reduce) {
  .hk-rise,
  .hk-fade-up,
  .hk-thread {
    animation: none !important;
    transform: none !important;
    opacity: 1 !important;
  }
  .hk-glow-a,
  .hk-glow-b,
  .hk-float {
    animation: none !important;
  }
  .hk-weft-line,
  .hk-warp-line {
    animation: none !important;
    stroke-dashoffset: 0 !important;
  }
  .hk-shuttle {
    animation: none !important;
    opacity: 0.25;
  }
}

