    phone1: "+251 911 234 567",
    phone2: "+251 908 765 432",
    telegram: "https://t.me/HabeshaKamisTailorShop",
    telegramUsername: "@HabeshaKamisTailorShop",
    email: "contact@habeshakamis.et",
    address: "Bole Medhanialem Mall, 3rd Floor, Suite 304, Addis Ababa, Ethiopia",
    openingHours: "Monday – Saturday: 9:00 AM – 7:00 PM (Sunday by Appointment)",
    announcement: "Now accepting custom wedding bookings for the upcoming holiday season.",
    heroImage: "/hero_kemis.jpg",
    storyImage: "/hero_kemis.jpg",
    catImageWedding: "/hero_kemis.jpg",
    catImageFemale: "/hero_kemis.jpg",
    catImageMale: "/hero_kemis.jpg",
    catImageFamily: "/hero_kemis.jpg"
  });
  const [homeImageFiles, setHomeImageFiles] = useState<Record<string, File | null>>({});
  const [activity, setActivity] = useState<any[]>([]);
  const [stats, setStats] = useState<any>({
    totalOrders: 0,
    inProduction: 0,
    pendingOrders: 0,
    totalDesigns: 0,
    totalInquiries: 0,
    unreadInquiries: 0,
    estimatedVisitorsToday: 142
  });

  const [isLoading, setIsLoading] = useState(true);
  const [savedSettingsSuccess, setSavedSettingsSuccess] = useState(false);

  const [orderFilter, setOrderFilter] = useState("all");
  const [searchQuery, setSearchQuery] = useState("");
  const [selectedOrder, setSelectedOrder] = useState<OrderItem | null>(null);

  const [isAddDesignOpen, setIsAddDesignOpen] = useState(false);
  const [editingDesignId, setEditingDesignId] = useState<string | null>(null);
  const [isUploading, setIsUploading] = useState(false);
  const [designForm, setDesignForm] = useState({
    name: "",
    amharicName: "",
    category: "wedding",
    priceRange: "20,000 - 35,000 ETB",
    description: "",
    material: "100% Fine Ethiopian Menen Cotton",
    weaveTime: "80 Hours",
    production: "2-3 Weeks",
    imageUrlFallback: ""
  });
  const [imageFile, setImageFile] = useState<File | null>(null);
  const [imagePreview, setImagePreview] = useState<string | null>(null);

  const fetchAllData = async () => {
    setIsLoading(true);
    try {
      const [ordersRes, designsRes, msgsRes, settingsRes, actRes] = await Promise.all([
        fetch("/api/admin/orders"),
        fetch("/api/admin/designs"),
        fetch("/api/admin/messages"),
        fetch("/api/admin/settings"),
        fetch("/api/admin/activity")
      ]);

      const [ordersData, designsData, msgsData, settingsData, actData] = await Promise.all([
        ordersRes.json(),
        designsRes.json(),
        msgsRes.json(),
        settingsRes.json(),
        actRes.json()
      ]);

      if (Array.isArray(ordersData)) setOrders(ordersData);
      if (Array.isArray(designsData)) setDesigns(designsData);
      if (Array.isArray(msgsData)) setMessages(msgsData);
      if (settingsData && !settingsData.error) setSettings(settingsData);
      if (actData && actData.stats) {
        setStats(actData.stats);
        setActivity(actData.recentActivity || []);
      }
    } catch (err) {
      console.error("Failed to load admin data", err);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchAllData();
  }, []);

  const handleUpdateOrderStatus = async (orderId: string, newStatus: string) => {
    try {
      const res = await fetch("/api/admin/orders", {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ id: orderId, status: newStatus })
      });
      if (res.ok) {
        setOrders(orders.map((o) => (o.id === orderId ? { ...o, status: newStatus } : o)));
        if (selectedOrder?.id === orderId) {
          setSelectedOrder({ ...selectedOrder, status: newStatus });
        }
      }
    } catch (err) {
      console.error(err);
    }
  };

  const handleDeleteOrder = async (orderId: string) => {
    if (!confirm("Are you sure you want to delete this order?")) return;
    try {
      const res = await fetch(`/api/admin/orders?id=${orderId}`, { method: "DELETE" });
      if (res.ok) {
        setOrders(orders.filter((o) => o.id !== orderId));
        if (selectedOrder?.id === orderId) setSelectedOrder(null);
      }
    } catch (err) {
      console.error(err);
    }
  };

  const handleDeleteDesign = async (designId: string) => {
    if (!confirm("Are you sure you want to remove this design from the gallery catalog?")) return;
    try {
      const res = await fetch(`/api/admin/designs?id=${designId}`, { method: "DELETE" });
      if (res.ok) {
        setDesigns(designs.filter((d) => d.id !== designId));
      }
    } catch (err) {
      console.error(err);
    }
  };

  const handleUpdateMessageStatus = async (msgId: string, newStatus: string) => {
    try {
      const res = await fetch("/api/admin/messages", {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ id: msgId, status: newStatus })
      });
      if (res.ok) {
        setMessages(messages.map((m) => (m.id === msgId ? { ...m, status: newStatus } : m)));
      }
    } catch (err) {
      console.error(err);
    }
  };

  const handleHomeImageFileChange = (key: string, e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0] || null;
    setHomeImageFiles({ ...homeImageFiles, [key]: file });
  };

  const handleSaveSettings = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const hasNewImages = Object.values(homeImageFiles).some(Boolean);
      let res: Response;

      if (hasNewImages) {
        // Send multipart so new image files can be uploaded together with the settings
        const formData = new FormData();
        for (const [key, value] of Object.entries(settings)) {
          formData.append(key, String(value ?? ""));
        }
        for (const [key, file] of Object.entries(homeImageFiles)) {
          if (file) formData.append(key, file);
        }
        res = await fetch("/api/admin/settings", { method: "PATCH", body: formData });
      } else {
        res = await fetch("/api/admin/settings", {
          method: "PATCH",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(settings)
        });
      }

      if (res.ok) {
        setSavedSettingsSuccess(true);
        setTimeout(() => setSavedSettingsSuccess(false), 3000);
        if (hasNewImages) {
          setHomeImageFiles({});
          // Reload so image previews reflect the freshly uploaded paths
          const updated = await res.json();
          if (updated?.settings) setSettings(updated.settings);
        }
      }
    } catch (err) {
      console.error(err);
    }
  };

  const handleImageFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setImageFile(file);
      setImagePreview(URL.createObjectURL(file));
    }
  };

  const resetDesignForm = () => {
    setDesignForm({
      name: "",
      amharicName: "",
      category: "wedding",
      priceRange: "20,000 - 35,000 ETB",
      description: "",
      material: "100% Fine Ethiopian Menen Cotton",
      weaveTime: "80 Hours",
      production: "2-3 Weeks",
      imageUrlFallback: ""
    });
    setImageFile(null);
    setImagePreview(null);
  };

  const handleOpenEditDesign = (design: DesignItem) => {
    setEditingDesignId(design.id);
    setDesignForm({
      name: design.name,
      amharicName: design.amharicName || "",
      category: design.category,
      priceRange: design.priceRange || "",
      description: design.description || "",
      material: design.specs?.material || "",
      weaveTime: design.specs?.weaveTime || "",
      production: design.specs?.production || "",
      imageUrlFallback: ""
    });
    setImageFile(null);
    setImagePreview(design.images?.[0] || null);
    setIsAddDesignOpen(true);
  };

  const handleCloseDesignModal = () => {
    setIsAddDesignOpen(false);
    setEditingDesignId(null);
    resetDesignForm();
  };

  const handleAddDesignSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!designForm.name) return;

    setIsUploading(true);

    try {
      const formData = new FormData();
      formData.append("name", designForm.name);
      formData.append("amharicName", designForm.amharicName);
      formData.append("category", designForm.category);
      formData.append("priceRange", designForm.priceRange);
      formData.append("description", designForm.description);
      formData.append("material", designForm.material);
      formData.append("weaveTime", designForm.weaveTime);
      formData.append("production", designForm.production);

      if (editingDesignId) {
        // EDIT MODE: PATCH the existing design
        formData.append("id", editingDesignId);

        if (imageFile && imagePreview !== designs.find((d) => d.id === editingDesignId)?.images?.[0]) {
          formData.append("imageFile", imageFile);
        }
        if (designForm.imageUrlFallback.trim()) {
          formData.append("imageUrl", designForm.imageUrlFallback.trim());
        }

        const res = await fetch("/api/admin/designs", { method: "PATCH", body: formData });
