        {children}
        <span>{en}</span>
      </span>
      <span className="text-[9px] normal-case tracking-wider font-light opacity-80 leading-none">
        {am}
      </span>
    </>
  );

  if (external) {
    return (
      <a href={href} target="_blank" rel="noopener noreferrer" className={classes}>
        {label}
      </a>
    );
