  href,
  en,
  am,
  variant = "gold",
  external = false,
  className = "",
  children,
}: CtaButtonProps) {
  const classes = `inline-flex flex-col items-center justify-center gap-1 rounded-sm px-7 py-3.5 text-xs uppercase tracking-[0.2em] transition duration-300 ${VARIANT_CLASSES[variant]} ${className}`;

  const label = (
